import{_ as i,o as a,c as o,a2 as t}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"Presentazioni","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/presentazioni.md","filePath":"user-guide/presentazioni.md"}'),n={name:"user-guide/presentazioni.md"};function l(s,e,r,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="presentazioni" tabindex="-1">Presentazioni <a class="header-anchor" href="#presentazioni" aria-label="Permalink to &quot;Presentazioni&quot;">​</a></h1><p>Ci sono due modi di presentare. Ogni nota Markdown può diventare una presentazione, senza un formato a parte: la nota resta un normale file <code>.md</code> leggibile anche da altri editor (le prime tre sezioni). Per slide curate nell&#39;aspetto esistono poi i file <code>.marp</code>, presentazioni Marp con editor, scheda Slideshow, presentazione a tutto schermo ed export in HTML, PDF e PowerPoint (sezione <a href="#presentazioni-marp-marp">Presentazioni Marp</a>).</p><h2 id="dividere-in-slide" tabindex="-1">Dividere in slide <a class="header-anchor" href="#dividere-in-slide" aria-label="Permalink to &quot;Dividere in slide&quot;">​</a></h2><p>Una slide finisce dove c&#39;è una riga con tre trattini (<code>---</code>) <strong>preceduta da una riga vuota</strong>. Il comando <em>Inserisci separatore</em> (o l&#39;icona nelle azioni rapide) la scrive per voi.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Titolo</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Introduzione.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Secondo punto</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> uno</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> due</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Note: ricordare l&#39;esempio dei grafi</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Chiusura</span></span></code></pre></div><ul><li>Una riga di trattini subito sotto un testo, senza riga vuota, è un titolo di secondo livello e <strong>non</strong> divide la slide.</li><li>I separatori dentro un blocco di codice o di formule (<code>$$ … $$</code>) e nel frontmatter non contano.</li><li>Le righe vuote iniziali e finali di una slide e le slide vuote sono ignorate. Una nota senza separatori è una presentazione di una sola slide.</li><li>Le <strong>note del presentatore</strong> sono le righe dopo una riga che comincia con <code>Note:</code> (maiuscole indifferenti), fino alla fine della slide. Non compaiono sulla slide.</li><li>Immagini, formule, diagrammi Mermaid, callout e incorporamenti si vedono come nella vista lettura; non si scarica nulla da internet.</li></ul><h2 id="avviare-la-presentazione" tabindex="-1">Avviare la presentazione <a class="header-anchor" href="#avviare-la-presentazione" aria-label="Permalink to &quot;Avviare la presentazione&quot;">​</a></h2><ul><li>Scheda <strong>Slide</strong> nella barra laterale destra: <em>Avvia la presentazione</em>, <em>Dalla slide corrente</em> (usa la posizione del cursore) o un clic su una miniatura per partire da quella slide.</li><li>Palette comandi: <em>Avvia la presentazione</em> e <em>Avvia la presentazione dalla slide corrente</em>.</li></ul><p>La presentazione occupa l&#39;intera finestra (e lo schermo intero, dove il sistema lo consente) ed è sempre al 100%: lo zoom dell&#39;interfaccia (Aspetto → Zoom) non vale durante la presentazione e torna all&#39;uscita. Lo stesso vale per le presentazioni Marp, dei disegni e per il canvas a tutto schermo.</p><table tabindex="0"><thead><tr><th>Azione</th><th>Tasti</th></tr></thead><tbody><tr><td>Slide successiva</td><td><code>→</code>, <code>↓</code>, <code>Pag↓</code>, <code>Spazio</code>, <code>Invio</code>, clic</td></tr><tr><td>Slide precedente</td><td><code>←</code>, <code>↑</code>, <code>Pag↑</code>, <code>Indietro</code></td></tr><tr><td>Prima / ultima slide</td><td><code>Home</code> / <code>Fine</code></td></tr><tr><td>Vista presentatore (attiva/disattiva)</td><td><code>P</code></td></tr><tr><td>Termina</td><td><code>Esc</code></td></tr></tbody></table><p>La <strong>vista presentatore</strong> mostra la slide corrente, la successiva, le note e il tempo trascorso. Tutto avviene nella stessa finestra: non c&#39;è uno schermo separato per il pubblico.</p><h2 id="opzioni" tabindex="-1">Opzioni <a class="header-anchor" href="#opzioni" aria-label="Permalink to &quot;Opzioni&quot;">​</a></h2><p>Nella scheda <em>Slide</em>, e salvate nel frontmatter della nota (quindi viaggiano con il file e si sincronizzano come ogni altra proprietà):</p><table tabindex="0"><thead><tr><th>Opzione</th><th>Proprietà</th><th>Valori</th></tr></thead><tbody><tr><td>Transizione</td><td><code>slide-transition</code></td><td><code>none</code>, <code>fade</code>, <code>slide</code> (predefinita), <code>zoom</code></td></tr><tr><td>Tema</td><td><code>slide-theme</code></td><td><code>auto</code> (come l&#39;applicazione), <code>light</code>, <code>dark</code></td></tr><tr><td>Barra di avanzamento</td><td><code>slide-progress</code></td><td><code>true</code> (predefinito) / <code>false</code></td></tr><tr><td>Numero di slide</td><td><code>slide-numbers</code></td><td><code>true</code> / <code>false</code> (predefinito)</td></tr><tr><td>Note nella vista presentatore</td><td><code>slide-notes</code></td><td><code>true</code> (predefinito) / <code>false</code></td></tr></tbody></table><p>Un valore non valido viene ignorato e vale il predefinito. Con il movimento ridotto attivo nel sistema le transizioni sono disattivate. Su un vault condiviso in sola lettura le opzioni non si possono modificare, ma si può presentare.</p><h2 id="presentazioni-marp-marp" tabindex="-1">Presentazioni Marp (<code>.marp</code>) <a class="header-anchor" href="#presentazioni-marp-marp" aria-label="Permalink to &quot;Presentazioni Marp (\`.marp\`)&quot;">​</a></h2><p>Una presentazione Marp è un file <code>.marp</code> nel vault: testo Markdown con il frontmatter <code>marp: true</code>, in cui le slide sono divise da <code>---</code>. Il comando <em>Nuova presentazione</em> (palette comandi) ne crea una con due slide. Per la sync è Markdown: unione a 3 vie, ricerca e link. Si usano i temi integrati di Marp (Predefinito, Gaia, Uncover), senza CSS proprio, e nessuna risorsa arriva dalla rete. L&#39;amministratore può spegnere la funzione dal Config Profile (<code>features.presentations</code>).</p><h3 id="l-editor" tabindex="-1">L&#39;editor <a class="header-anchor" href="#l-editor" aria-label="Permalink to &quot;L&#39;editor&quot;">​</a></h3><p>Il <code>.marp</code> si apre in un editor del solo sorgente, a tutta larghezza: non c&#39;è vista divisa né i pulsanti Live, Sorgente e Lettura. L&#39;anteprima delle slide sta nella scheda Slideshow della barra destra.</p><h3 id="la-scheda-slideshow" tabindex="-1">La scheda Slideshow <a class="header-anchor" href="#la-scheda-slideshow" aria-label="Permalink to &quot;La scheda Slideshow&quot;">​</a></h3><p>Con un <code>.marp</code> attivo, la scheda <em>Slide</em> della barra destra (<em>Slideshow</em>) mostra «Slideshow · n di m slide incluse» e una card per slide. La slide sotto il cursore dell&#39;editor è evidenziata.</p><p>Barra degli strumenti:</p><ul><li><em>Avvia la presentazione</em>, dalla prima slide inclusa;</li><li><em>Stampa / salva come PDF</em>;</li><li><em>Informazioni sulla presentazione</em>: slide, incluse nella presentazione, tema, parole, slide con note;</li><li><em>Impostazioni di presentazione</em>: <em>Ricomincia alla fine</em>, <em>Numeri di pagina sulle slide</em>, <em>Mostra le note del relatore</em>, <em>Tema</em> (<em>Predefinito</em>, <em>Gaia</em>, <em>Uncover</em>);</li><li>il menu <em>Altre azioni</em>: <em>Includi tutte le diapositive</em> ed <em>Escludi tutte le diapositive</em>.</li></ul><p>Ogni card ha il titolo («1. Titolo»: il primo titolo della slide, altrimenti la prima riga di testo), la miniatura e i pulsanti:</p><ul><li><em>Vai a questa slide nell&#39;editor</em> (la matita);</li><li><em>Sposta su</em> e <em>Sposta giù</em>: scambiano i blocchi di testo tra i separatori <code>---</code>;</li><li><em>Includi nella presentazione</em> / <em>Escludi dalla presentazione</em> (l&#39;occhio);</li><li><em>Avvia da questa diapositiva</em>.</li></ul><p>Un clic su una card la seleziona, porta il cursore dell&#39;editor sulla slide e apre la casella delle <em>Note del relatore</em> (Markdown), che si salvano da sole poco dopo la digitazione.</p><p>Tutte queste azioni modificano il testo del file e si annullano con l&#39;undo dell&#39;editor; su un vault in sola lettura sono disattivate. Con le slide divise dai titoli (direttiva <code>headingDivider</code>) non ci sono separatori e quindi <em>Sposta su</em> e <em>Sposta giù</em> restano disattivati.</p><h3 id="che-cosa-viene-scritto-nel-file" tabindex="-1">Che cosa viene scritto nel file <a class="header-anchor" href="#che-cosa-viene-scritto-nel-file" aria-label="Permalink to &quot;Che cosa viene scritto nel file&quot;">​</a></h3><ul><li><strong>Slide escluse:</strong> il commento <code>&lt;!-- clarae: hidden --&gt;</code> dentro la slide. Un&#39;esclusione vale solo in Clarae notanda: un client più vecchio o un altro strumento Marp mostra la slide e può leggere il commento come nota. Le esclusioni scritte dalla 1.x si leggono ancora e non vengono riscritte; includere di nuovo la slide toglie il marcatore, qualunque sia.</li><li><strong>Note del relatore:</strong> commenti HTML nella slide, come vuole Marp (<code>&lt;!-- testo della nota --&gt;</code>). Un commento che contiene direttive di Marp (per esempio <code>theme: gaia</code>) è configurazione, non una nota; se si scrive una nota che sembra una direttiva, Clarae notanda vi inserisce un carattere invisibile perché Marp non la legga come tale. Un commento dentro un blocco di codice (recintato o rientrato) o tra apici inversi non è una nota e non viene toccato.</li><li><strong>Impostazioni:</strong> il tema e i numeri di pagina sono le direttive <code>theme</code> e <code>paginate</code> del frontmatter; <em>Ricomincia alla fine</em> e <em>Mostra le note del relatore</em> sono le chiavi <code>clarae-loop</code> (<code>true</code> per ripetere) e <code>clarae-notes</code> (<code>false</code> per nasconderle; altrimenti sono visibili). Marp e i client precedenti le ignorano: una presentazione scritta dalla 1.x si legge ancora, e cambiare una di queste impostazioni scrive la chiave nuova e toglie la vecchia nella stessa modifica (un solo annulla). Un dispositivo con la 1.4 non riconosce le chiavi nuove: «ricomincia alla fine» e le note del relatore tornano ai valori di partenza.</li></ul><h3 id="presentare" tabindex="-1">Presentare <a class="header-anchor" href="#presentare" aria-label="Permalink to &quot;Presentare&quot;">​</a></h3><p><em>Avvia la presentazione</em> (barra della scheda, card, oppure il comando <em>Presenta le slide</em>) apre la presentazione a tutto schermo, dove il sistema lo consente. Mostra le slide incluse del testo come è nell&#39;editor, anche non salvato. I numeri di pagina seguono Marp: le slide escluse non lasciano buchi nella numerazione.</p><table tabindex="0"><thead><tr><th>Azione</th><th>Tasti</th></tr></thead><tbody><tr><td>Slide successiva</td><td><code>→</code>, <code>↓</code>, <code>Pag↓</code>, <code>Spazio</code>, <code>Invio</code></td></tr><tr><td>Slide precedente</td><td><code>←</code>, <code>↑</code>, <code>Pag↑</code>, <code>Indietro</code></td></tr><tr><td>Prima / ultima slide</td><td><code>Home</code> / <code>Fine</code></td></tr><tr><td>Termina</td><td><code>Esc</code>, o il pulsante di chiusura</td></tr></tbody></table><p>La barra in basso ha i pulsanti precedente e successiva, l&#39;elenco delle slide, «n / totale» e, se attive, le note del relatore. Con <em>Ricomincia alla fine</em> dopo l&#39;ultima slide si riparte dalla prima. Uscire dallo schermo intero chiude la presentazione. Non ci sono la vista presentatore (<code>P</code>) né il clic per avanzare, che sono delle note Markdown.</p><h3 id="esportare" tabindex="-1">Esportare <a class="header-anchor" href="#esportare" aria-label="Permalink to &quot;Esportare&quot;">​</a></h3><p>I pulsanti di esportazione stanno nel ribbon, a sinistra, e cambiano con il file attivo: con una presentazione sono HTML, PDF e PPTX (gli stessi comandi sono nella palette: <em>Esporta la presentazione in HTML</em>, <em>…in PDF</em>, <em>…in PowerPoint (PPTX)</em>). Le slide escluse restano fuori da tutti e tre.</p><ul><li><strong>HTML:</strong> un file autonomo, con le slide e il tema.</li><li><strong>PDF:</strong> apre la finestra di stampa del sistema, dove scegliere «Salva come PDF».</li><li><strong>PPTX:</strong> un file PowerPoint con testo modificabile (titoli, elenchi, tabelle, codice, immagini, sfondi), note del relatore e numeri di pagina, che si apre in PowerPoint e Keynote. Nel browser viene scaricato. Limiti: il tema è approssimato (colori e font di Predefinito, Gaia e Uncover, classi <code>invert</code> e <code>lead</code>), quindi l&#39;aspetto è vicino ma non identico all&#39;HTML; le immagini che non si riescono a convertire (per esempio certi SVG) sono saltate e l&#39;app le elenca al termine.</li></ul>`,36)])])}const h=i(n,[["render",l]]);export{u as __pageData,h as default};
